    const px = img.data;
    for (let i = 0; i < n; i++) { const k = own[i]; if (k < 0) continue; const c = acc[k]; c.a++; c.sx += i % w; c.sy += (i / w) | 0; c.H += D.A[i]; c.B += D.B[i]; c.T += D.T[i]; c.br += (px[i * 4] - px[i * 4 + 2]) / 255; }
